import json
import pandas as pd
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse various date formats to YYYY-MM-DD"""
    if pd.isna(date_str) or date_str is None:
        return None

    date_str = str(date_str).strip()
    if not date_str:
        return None

    # Already in correct format
    if len(date_str) == 10 and date_str[4] == '-' and date_str[7] == '-':
        return date_str

    # Try common formats
    for fmt in ['%Y-%m-%d', '%Y/%m/%d', '%d-%m-%Y', '%d/%m/%Y', '%m-%d-%Y', '%m/%d/%Y']:
        try:
            return datetime.strptime(date_str, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue

    return date_str

def load_source_a():
    """Load and normalize source A (JSON)"""
    with open('/data/source_a/users.json', 'r') as f:
        data = json.load(f)

    normalized = []
    for record in data:
        normalized.append({
            'user_id': record.get('id'),
            'name': record.get('full_name'),
            'email': record.get('email'),
            'created_date': parse_date(record.get('registration_date')),
            'status': record.get('status'),
            'source': 'source_a'
        })

    return normalized

def load_source_b():
    """Load and normalize source B (CSV)"""
    df = pd.read_csv('/data/source_b/users.csv')

    normalized = []
    for _, row in df.iterrows():
        # Map is_active to status if available
        status = None
        if 'is_active' in df.columns:
            status = 'active' if row.get('is_active') else 'inactive'

        normalized.append({
            'user_id': row.get('user_id'),
            'name': row.get('name'),
            'email': row.get('email_address'),
            'created_date': parse_date(row.get('created_at')),
            'status': status,
            'source': 'source_b'
        })

    return normalized

def load_source_c():
    """Load and normalize source C (Parquet)"""
    df = pd.read_parquet('/data/source_c/users.parquet')

    normalized = []
    for _, row in df.iterrows():
        # Map active boolean to status
        status = None
        if 'active' in df.columns and pd.notna(row.get('active')):
            status = 'active' if row['active'] else 'inactive'

        normalized.append({
            'user_id': row.get('userId'),
            'name': row.get('userName'),
            'email': row.get('email'),
            'created_date': parse_date(row.get('joined')),
            'status': status,
            'source': 'source_c'
        })

    return normalized

def merge_users():
    """Merge all sources with conflict tracking"""
    # Load all sources
    source_a_records = load_source_a()
    source_b_records = load_source_b()
    source_c_records = load_source_c()

    # Index records by user_id
    sources = {
        'source_a': {r['user_id']: r for r in source_a_records},
        'source_b': {r['user_id']: r for r in source_b_records},
        'source_c': {r['user_id']: r for r in source_c_records}
    }

    # Find all unique user IDs
    all_user_ids = set()
    for source_records in sources.values():
        all_user_ids.update(source_records.keys())

    # Priority order
    priority = ['source_a', 'source_b', 'source_c']

    # Merge records
    merged = {}
    conflicts = []

    for user_id in sorted(all_user_ids):
        # Get records from each source for this user
        user_records = {
            source: sources[source].get(user_id)
            for source in priority
        }

        # Select values based on priority
        merged_record = {'user_id': user_id}
        fields = ['name', 'email', 'created_date', 'status']

        for field in fields:
            selected_value = None
            field_values = {}

            for source in priority:
                if user_records[source] is not None:
                    value = user_records[source].get(field)
                    if value is not None:
                        field_values[source] = value
                        if selected_value is None:
                            selected_value = value

            merged_record[field] = selected_value

            # Check for conflicts
            unique_values = set(v for v in field_values.values() if v is not None)
            if len(unique_values) > 1:
                conflicts.append({
                    'user_id': user_id,
                    'field': field,
                    'values': field_values,
                    'selected': selected_value
                })

        merged[user_id] = merged_record

    return merged, conflicts

def main():
    # Merge data
    merged_users, conflicts = merge_users()

    # Convert to list and prepare for output
    merged_list = list(merged_users.values())

    # Create DataFrame
    df = pd.DataFrame(merged_list)

    # Ensure correct data types
    df['user_id'] = df['user_id'].astype('int64')

    # Save to parquet
    output_parquet = Path('/app/merged_users.parquet')
    output_parquet.parent.mkdir(parents=True, exist_ok=True)
    df.to_parquet(output_parquet, index=False)

    print(f"✓ Merged {len(df)} unique users to {output_parquet}")

    # Save conflicts report
    conflict_report = {
        'total_conflicts': len(conflicts),
        'conflicts': conflicts
    }

    output_conflicts = Path('/app/conflicts.json')
    with open(output_conflicts, 'w') as f:
        json.dump(conflict_report, f, indent=2)

    print(f"✓ Saved conflict report to {output_conflicts}")
    print(f"\nMerge Summary:")
    print(f"  Total unique users: {len(df)}")
    print(f"  Total conflicts: {len(conflicts)}")

    if conflicts:
        print(f"\nConflicts by field:")
        field_conflicts = {}
        for conflict in conflicts:
            field = conflict['field']
            field_conflicts[field] = field_conflicts.get(field, 0) + 1

        for field, count in sorted(field_conflicts.items()):
            print(f"  {field}: {count}")

    print(f"\nMerged data preview:")
    print(df.to_string())

if __name__ == '__main__':
    main()

