            return datetime.strptime(date_str, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue

    return date_str

def load_source_a():
    """Load and normalize source A (JSON)"""
    with open('/data/source_a/users.json', 'r') as f:
        data = json.load(f)

    normalized = []
    for record in data:
        normalized.append({
            'user_id': record.get('id'),
            'name': record.get('full_name'),
            'email': record.get('email'),
            'created_date': parse_date(record.get('registration_date')),
            'status': record.get('status'),
            'source': 'source_a'
        })

    return normalized

def load_source_b():
    """Load and normalize source B (CSV)"""
    df = pd.read_csv('/data/source_b/users.csv')

    normalized = []
    for _, row in df.iterrows():
        # Map is_active to status if available
        status = None
        if 'is_active' in df.columns:
            status = 'active' if row.get('is_active') else 'inactive'

        normalized.append({
            'user_id': row.get('user_id'),
            'name': row.get('name'),
